* Frequency of management earnings forecasts
use "gdet_lnk_new.dta", clear

* Basic financial data from Compustat;
%let fyear1= 1984; %let fyear2= 2017;
%let vars = gvkey datadate fyear sich cusip cik
        prcc_f csho AJEX at ceq ib OANCF sale
        INDFMT DATAFMT POPSRC CONSOL;


data controls;
  set comp.funda (keep= &vars);
  where fyear between &fyear1 and &fyear2;

 if indfmt='INDL' and datafmt='STD' and popsrc='D' and consol='C';
 drop indfmt datafmt popsrc consol;
 endfyr= datadate; format endfyr date9.;
 begfyr= intnx('month',endfyr,-11,'beg'); format begfyr date9.;
run;
proc sort; by gvkey endfyr; run;

* Earnings volatility;
proc sql undo_policy = none;
 create table controls
 as select distinct a.*,count(b.roa) as numroa
 from controls a left join controls b

 on a.gvkey=b.gvkey
 and 0<a.fyear-b.fyear<=10
 and not missing(b.roa)
 group by a.gvkey, a.fyear
 order by a.gvkey, a.fyear;
quit;
proc sort nodupkey; by gvkey fyear;run;


proc sql undo_policy = none;
 create table controls
 as select distinct a.*,std(b.roa) as earnvol
 from controls a left join controls b
 on a.gvkey=b.gvkey
 and 0<a.fyear-b.fyear<=10
 and a.numroa>=5 and not missing(b.roa)
 group by a.gvkey, a.fyear
 order by a.gvkey, a.fyear;

