* Link permno using the three link table;
proc sql;
        create table gdetlink1
        as select a.*,
                b.permno,
                c.permno as cpermno,
                d.permno as dpermno
        from mf as a
        left join linkwrds.ibes_tkr_permno (where=(score=1 or 2)) as b
        on a.ticker=b.ticker
        and ((b.sdate<=a.anndats<=b.edate) or (b.sdate<=a.anndats and b.edate=.) or (b.sdate=.
and a.anndats<=b.edate))

        left join iclink (where=(score=0 or 1)) as c
        on a.ticker=c.ticker
        left join linkm.ibes_ticker_permno (where=(dup1=0 and dup2=0 and

* lnk mf to gvkey;
* lnk table:
* 1) cibeslnk;
* 2) comp.security;
proc import out=security
        datafile='[redacted-path-b9565ce2d963]'
        dbms=dta replace;
run;


proc sql;
        create table gdetlink2 as
        select a.*, b.gvkey, c.gvkey as dgvkey
        from gdetlink1 as a
        left join link.cibeslnk as b
        on a.ticker=b.ticker
        and ((b.fdate<=a.anndats<=b.ldate) or (b.fdate<=a.anndats and b.ldate=.E)
        or (b.fdate=.B and a.anndats <=b.ldate))
        left join security as c

* more gvkey from ccm;
proc sql;
       create table gdetlink3 as
       select a.*, b.gvkey as cgvkey
       from gdetlink2 as a
       left join crsp.ccmxpf_lnkhist
       (where=(linkprim in ('P', 'C') and linktype in ('LU', 'LC'))) as b
       on a.permno=b.lpermno

        and ((b.linkdt<=a.anndats<=b.linkenddt)
        or (b.linkdt<=a.anndats and b.linkenddt=.E) or (b.linkdt=.B and a.anndats<=b.linkenddt))
        order by ticker, prd_yr, prd_mon, anndats,
               pdicity, measure, val_1, val_2;
quit;


data gdetlink3 (drop=cgvkey);
        set gdetlink3;
        if gvkey=. and cgvkey ^=.
        then gvkey=cgvkey;
run;


proc sort
        data=gdetlink3 nodupkey;
        by ticker permno gvkey
               prd_yr prd_mon anndats
               pdicity measure val_1 val_2;
run;


*more permno from ccm;
proc sql;
        create table gdetlink4 as
        select a.*, b.lpermno
        from gdetlink3 as a
        left join crsp.ccmxpf_lnkhist
        (where=(linkprim in ('P', 'C') and linktype in ('LU', 'LC'))) as b
        on a.gvkey=b.gvkey
        and ((b.linkdt<=a.anndats<=b.linkenddt)
        or (b.linkdt<=a.anndats and b.linkenddt=.E) or (b.linkdt=.B and a.anndats<=b.linkenddt))
        order by ticker, prd_yr, prd_mon, anndats,
               pdicity, measure, val_1, val_2;

quit;


data gdetlink4 (drop=lpermno);
        set gdetlink4;
        if permno=. and lpermno ^=.
        then permno=lpermno;
run;


proc sort
        data=gdetlink4 nodupkey;
        by ticker permno gvkey
               prd_yr prd_mon anndats
               pdicity measure val_1 val_2;
run;




