*to add the IBES ticker;
proc sql;
    create table comp2
    as select a.*,b.ticker, c.ibtic
    from comp1 a
    left join cibeslnk b

    on a.gvkey= b.gvkey and b.fdate <= a.datadate <=b.ldate
            left join security c
            on a.gvkey=c.gvkey;
quit;


data comp2 (drop=ibtic);
   set comp2;
        if ticker="" and ibtic^="" then ticker=ibtic;
run;


proc sort data=comp2 out=comp3 nodupkey;
where not missing(ticker);
by gvkey datadate;
run;




* merge with statsumu_epsus;
data comp4;
set comp3;
IBES_date = intnx('month',datadate, 0,'end');
format datadate YYMMDD10. IBES_date YYMMDD10.;
run;




proc sql;
    create table comp5
    as select a.*, b.*
    from comp4 a left join ibes.statsumu_epsus b
    on a.ticker = b.ticker and a.datadate = b.fpedats and b.statpers <= a.IBES_date and
b.statpers >= a.IBES_date - 90 and
        b.FPI = '1' and b.measure ='EPS';

quit;


proc sort data=comp5 out=comp6 nodupkey;
by gvkey datadate descending statpers;
run;




*right before the year end;
data comp7;
set comp6;
where not missing(numest);
by gvkey datadate descending statpers;
if first.datadate = 1;
num_anal = numest;
for_std = stdev;
for_mean = meanest;
dispersion = for_std/abs(for_mean);
format IBES_date yymmdd10. statpers yymmdd10. fpedats yymmdd10.;
run;




data comp7;
  set comp7 (rename=(fyear=year));
  where not missing(gvkey);
run;


data comp7(drop=gvkey1);
  set comp7(rename=(gvkey=gvkey1));
  gvkey=gvkey1*1;
run;

proc sort data=comp7 nodupkey;
by gvkey year;
run;


